diff --git a/src/orders.test.ts b/src/orders.test.ts
index 6473e31..f73fdb5 100644
--- a/src/orders.test.ts
+++ b/src/orders.test.ts
@@ -1,8 +1,12 @@
 import { expect, test } from "bun:test";
-import { subtotalCents } from "./orders.ts";
+import { discountedCents, subtotalCents } from "./orders.ts";

 const order = { id: "o1", lines: [{ sku: "mug", unitCents: 450, quantity: 2 }, { sku: "tea", unitCents: 100, quantity: 1 }] };

 test("the subtotal sums every line", () => {
   expect(subtotalCents(order)).toBe(1000);
 });
+
+test("a discount takes its share off the subtotal", () => {
+  expect(discountedCents(order, 10)).toBe(900);
+});
diff --git a/src/orders.ts b/src/orders.ts
index 8701985..5149919 100644
--- a/src/orders.ts
+++ b/src/orders.ts
@@ -12,3 +12,9 @@ export interface Order {
 export function subtotalCents(order: Order): number {
   return order.lines.reduce((sum, line) => sum + line.unitCents * line.quantity, 0);
 }
+
+/** The order's total after a percentage off, from 0 to 100. */
+export function discountedCents(order: Order, percentOff: number): number {
+  if (!(percentOff >= 0 && percentOff <= 100)) throw new RangeError(`percentOff ${percentOff} is not between 0 and 100`);
+  return subtotalCents(order) * (1 - percentOff / 100);
+}
